package run.ikaros.music;
import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentMusicPlaybackService implements MusicPlaybackService{private final MusicTrackRepository tracks;private final MusicAudioSourceRepository sources;private final MusicPlaybackSessionRepository sessions;private final MusicPlaybackHistoryRepository history;public PersistentMusicPlaybackService(MusicTrackRepository t,MusicAudioSourceRepository s,MusicPlaybackSessionRepository p,MusicPlaybackHistoryRepository h){tracks=t;sources=s;sessions=p;history=h;}
 @Override public Mono<MusicPlaybackSessionView> start(UUID o,UUID track,StartMusicPlaybackRequest r){if(r.positionMillis()<0)return Mono.error(new IllegalArgumentException("播放位置不能为负数"));return tracks.findById(track).filter(t->t.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Track 不存在或无权访问"))).then(sources.findById(r.sourceId()).filter(s->s.ownerId().equals(o)&&s.trackId().equals(track)&&"AVAILABLE".equals(s.availability())).switchIfEmpty(Mono.error(new NotFoundException("Audio Source 不存在或不可用")))).flatMap(s->{Instant now=Instant.now();return sessions.save(new MusicPlaybackSessionEntity(null,o,track,s.id(),r.queueId(),MusicPlaybackState.ACTIVE,now,now,null,r.positionMillis(),null));}).map(this::view);}
 @Override public Mono<MusicPlaybackSessionView> update(UUID o,UUID id,UpdateMusicPlaybackRequest r){return active(o,id).flatMap(s->sessions.save(new MusicPlaybackSessionEntity(s.id(),s.ownerId(),s.trackId(),s.sourceId(),s.queueId(),s.state(),s.startedAt(),Instant.now(),s.endedAt(),r.positionMillis(),s.version()))).map(this::view);}
 @Override public Mono<MusicPlaybackSessionView> end(UUID o,UUID id,EndMusicPlaybackRequest r){return active(o,id).flatMap(s->{Instant now=Instant.now();MusicPlaybackState outcome=r.outcome()==MusicPlaybackState.ACTIVE?MusicPlaybackState.ABANDONED:r.outcome();return sessions.save(new MusicPlaybackSessionEntity(s.id(),s.ownerId(),s.trackId(),s.sourceId(),s.queueId(),outcome,s.startedAt(),now,now,s.positionMillis(),s.version())).flatMap(done->history.save(new MusicPlaybackHistoryEntity(null,o,s.trackId(),s.sourceId(),s.startedAt(),now,Math.max(0,done.positionMillis()),outcome)).thenReturn(done));}).map(this::view);}
 @Override public Flux<MusicPlaybackHistoryView> history(UUID o){return history.findAllByOwnerIdOrderByEndedAtDesc(o).map(this::historyView);}private Mono<MusicPlaybackSessionEntity> active(UUID o,UUID id){return sessions.findById(id).filter(s->s.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Playback Session 不存在"))).flatMap(s->s.state()==MusicPlaybackState.ACTIVE?Mono.just(s):Mono.error(new ConflictException("Playback Session 已结束")));}private MusicPlaybackSessionView view(MusicPlaybackSessionEntity s){return new MusicPlaybackSessionView(s.id(),s.trackId(),s.sourceId(),s.queueId(),s.state(),s.startedAt(),s.endedAt(),s.positionMillis());}private MusicPlaybackHistoryView historyView(MusicPlaybackHistoryEntity h){return new MusicPlaybackHistoryView(h.id(),h.trackId(),h.sourceId(),h.startedAt(),h.endedAt(),h.listenedMillis(),h.outcome());}}
